import { BaseLitElement, webComponent } from '@domg-wc/common';
import { vlIconStyles, vlLinkStyles } from '@domg-wc/components/atom';
import { CSSResult, html, TemplateResult } from 'lit';

// vlLinkStyles(selector) geeft de elementen van de selector de opmaak van een link, zonder argument de <a>-elementen.
// vlIconStyles is enkel nodig voor een icoon in de link.
@webComponent('my-component-with-link')
export class MyComponentWithLink extends BaseLitElement {
    static get styles(): CSSResult[] {
        return [vlLinkStyles(), vlIconStyles];
    }

    render(): TemplateResult {
        return html`
            <a href="#" class="bold">Mijn link</a>
        `;
    }
}
